"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/how-it-works/variants/01-centered-cards";
import View1 from "./components/how-it-works/variants/02-process-grid";
import View2 from "./components/how-it-works/variants/03-story-stack";
