"use client";
// @zeus-internal
import { Check, ClipboardCheck, FileText, type LucideIcon, MessageSquareText, Rocket } from "lucide-react";
import { motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
const VIEWPORT = { once: true, margin: "-40px" } as const;
const NOTES: ReadonlyArray<{
    icon: LucideIcon;
    label: string;
    from: string;
}> = [
    { icon: MessageSquareText, label: "Customer note", from: "translate3d(-34px,0,0)" },
    { icon: FileText, label: "Original brief", from: "translate3d(34px,0,0)" },
