export function CaptureScene() {
    return (<div className="art:w-[78%] art:space-y-2">
      {NOTES.map(({ icon: Icon, label, from }, i) => (<motion.div key={label} className="art:flex art:items-center art:gap-3 art:rounded-xl art:border art:border-border/70 art:bg-background/75 art:px-3 art:py-2.5 art:backdrop-blur-md" initial={{ opacity: 0, filter: "blur(5px)", transform: from }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={VIEWPORT} transition={{ duration: 0.52, delay: i * 0.07, ease: ARTEMIS_EASE_OUT }}>
          <span className="art:flex art:size-8 art:items-center art:justify-center art:bg-muted art:text-muted-foreground art:rounded-full">
