      <div className="art:mb-3 art:flex art:items-center art:justify-between">
        <span className="art:font-medium art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.14em]">Shared brief</span>
        <ClipboardCheck className="art:size-3.5 art:text-muted-foreground"/>
      </div>
      <div className="art:space-y-1.5">
        {BRIEF_ITEMS.map((item, i) => (<motion.div key={item} className="art:flex art:items-center art:gap-2 art:rounded-lg art:bg-muted/65 art:px-2.5 art:py-2" initial={{ opacity: 0, transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={VIEWPORT} transition={{ duration: 0.42, delay: i * 0.07, ease: ARTEMIS_EASE_OUT }}>
            <Check className="art:size-3 art:text-muted-foreground"/>
            <span className="art:font-medium art:text-xs">{item}</span>
          </motion.div>))}
