}
export function LaunchScene() {
    return (<motion.div className="art:relative art:flex art:size-28 art:items-center art:justify-center art:rounded-3xl art:border art:border-border/70 art:bg-background/75 art:backdrop-blur-md" initial={{ opacity: 0, filter: "blur(7px)", transform: "scale(0.9)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "scale(1)" }} viewport={VIEWPORT} transition={{ duration: 0.58, ease: ARTEMIS_EASE_OUT }}>
      <span className="art:flex art:size-12 art:items-center art:justify-center art:bg-muted art:text-foreground art:rounded-full">
        <Rocket className="art:size-5"/>
      </span>
      <motion.span className="art:absolute art:-right-2 art:-bottom-2 art:flex art:size-9 art:items-center art:justify-center art:border art:border-border art:bg-background art:text-foreground art:rounded-full" initial={{ opacity: 0, transform: "translate3d(-6px,-6px,0) scale(0.8)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0) scale(1)" }} viewport={VIEWPORT} transition={{ duration: 0.45, delay: 0.18, ease: ARTEMIS_EASE_OUT }}>
        <Check className="art:size-4"/>
      </motion.span>
