"use client";
// @zeus-internal
import { ArtemisWordEntrance } from "../../../../lib/word-entrance";
export function WordReveal({ text, className }: { text: string; className: string }) {
  return <h2 className={className}><ArtemisWordEntrance words={text.split(" ")} stagger={0.06} yOffset="24%"/></h2>;
}

"use client";
// @zeus-internal
import { ArrowRight, type LucideIcon, MessageSquareText, Rocket, Rows3 } from "lucide-react";
import { motion, useInView } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";
import { ArtemisButton, ArtemisButtonLink } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import { CaptureScene, ShapeScene, ShipScene } from "./02-process-grid/scenes";
const AUTOPLAY_MS = 6400;
const LINES = [
    ["One", "clear", "path", "from"],
    ["raw", "input", "to", "release."],
] as const;
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "24%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: "0%" };
function wordTransition(index: number) {
    const delay = index * 0.065;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", stiffness: 70, damping: 13, mass: 0.6, delay },
    } as const;
}
const COPY_HIDDEN = { opacity: 0, filter: "blur(7px)", transform: "translate3d(0,12px,0)" };
const COPY_SHOWN = { opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" };
const CORNER = "art:pointer-events-none art:absolute art:z-20 art:size-4 art:before:absolute art:before:top-1/2 art:before:left-0 art:before:h-px art:before:w-full art:before:-translate-y-1/2 art:before:bg-foreground/20 art:after:absolute art:after:top-0 art:after:left-1/2 art:after:h-full art:after:w-px art:after:-translate-x-1/2 art:after:bg-foreground/20";
interface Step {
    number: string;
    label: string;
    title: string;
    body: string;
    icon: LucideIcon;
    scene: (active: boolean) => ReactNode;
}
const STEPS: readonly Step[] = [
    {
        number: "01",
        label: "Capture",
        title: "Bring the signal into focus",
        body: "Collect customer notes, requests, and loose ideas in one brief that keeps the original context intact.",
        icon: MessageSquareText,
        scene: (active) => <CaptureScene active={active}/>,
    },
    {
        number: "02",
        label: "Shape",
        title: "Turn context into a clear plan",
        body: "Organize the brief into decisions, owners, and the next work that will move the outcome forward.",
        icon: Rows3,
        scene: (active) => <ShapeScene active={active}/>,
    },
    {
        number: "03",
        label: "Ship",
        title: "Move the right version live",
        body: "Review the final details, publish with confidence, and keep the result visible to everyone involved.",
        icon: Rocket,
        scene: (active) => <ShipScene active={active}/>,
    },
];
function Heading() {
    const ref = useRef<HTMLHeadingElement>(null);
    const inView = useInView(ref, { once: true, amount: 0.4 });
    return (<h2 ref={ref} className="art:block art:mt-7 art:max-w-4xl art:text-balance art:tracking-[-0.055em] art:text-4xl art:font-medium">
      {LINES.map((line, lineIndex) => (<span key={line.join(" ")} className="art:block">
          {line.map((word, wordIndex) => {
                const index = LINES.slice(0, lineIndex).reduce((sum, l) => sum + l.length, 0) + wordIndex;
                return (<motion.span key={word} className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} animate={inView ? WORD_SHOWN : WORD_HIDDEN} transition={wordTransition(index)}>
                {word}
                {wordIndex < line.length - 1 ? (<span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span>) : null}
              </motion.span>);
            })}
        </span>))}
    </h2>);
}
function StepCard({ step, index, active, onSelect }: {
    step: Step;
    index: number;
    active: boolean;
    onSelect: () => void;
}) {
    const Icon = step.icon;
    return (<motion.article className="art:relative art:grid art:min-w-0 art:grid-rows-[13rem_auto] art:border-border/70 art:border-b art:transition-colors art:duration-500 art:last:border-b-0 art:@min-[768px]/artemis:grid-rows-[15rem_auto] art:@min-[768px]/artemis:border-r art:@min-[768px]/artemis:border-b-0 art:@min-[768px]/artemis:last:border-r-0 art:bg-background" initial={{ opacity: 0, filter: "blur(6px)" }} whileInView={{ opacity: 1, filter: "blur(0px)" }} viewport={{ once: true, margin: "-50px" }} transition={{ duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: index * 0.06 }}>
      <div className="art:relative art:overflow-hidden art:border-border/70 art:border-b">
        <div aria-hidden="true" className="art:absolute art:inset-0 art:bg-[radial-gradient(circle_at_50%_0%,hsl(var(--artemis-foreground)/0.07),transparent_58%)]"/>
        <div aria-hidden="true" className="art:absolute art:inset-0 art:p-5 art:@min-[640px]/artemis:p-6">
          {step.scene(active)}
        </div>
      </div>
      <ArtemisButton variant="link" size="none" className="art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-h-[14rem] art:w-full art:flex-col art:p-6 art:text-left art:outline-none art:transition-colors art:focus-visible:bg-muted/60 art:@min-[640px]/artemis:p-7 art:@min-[768px]/artemis:min-h-[15rem]" aria-pressed={active} onClick={onSelect}>
        <span className="art:flex art:w-full art:items-center art:justify-between">
          <span className="art:font-medium art:text-muted-foreground art:text-xs art:tabular-nums">{step.number}</span>
          <span className={artemisCx("art:grid art:size-9 art:place-items-center art:rounded-full art:transition-colors art:duration-300", active ? "art:bg-foreground art:text-background" : "art:bg-muted art:text-muted-foreground")}>
            <Icon strokeWidth={1.7} className="art:size-4"/>
          </span>
        </span>
        <span className="art:mt-8 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.15em]">{step.label}</span>
        <h3 className="art:mt-3 art:text-balance art:font-medium art:text-xl art:leading-[1.04] art:tracking-[-0.04em]">{step.title}</h3>
        <p className="art:mt-4 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{step.body}</p>
      </ArtemisButton>
    </motion.article>);
}
export default function HowItWorksProcessGrid() {
    const sectionRef = useRef<HTMLElement>(null);
    const headerRef = useRef<HTMLDivElement>(null);
    const sectionInView = useInView(sectionRef);
    const headerInView = useInView(headerRef, { once: true, amount: 0.25 });
    const [active, setActive] = useState(0);
    useEffect(() => {
        if (!sectionInView)
            return;
        const timer = window.setTimeout(() => setActive((current) => (current + 1) % STEPS.length), AUTOPLAY_MS);
        return () => window.clearTimeout(timer);
    }, [active, sectionInView]);
    return (<section ref={sectionRef} className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div ref={headerRef} className="art:grid art:items-end art:gap-8 art:@min-[1024px]/artemis:grid-cols-[1.25fr_0.75fr] art:@min-[1024px]/artemis:gap-16">
          <div>
            <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={{ opacity: 0, transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={{ once: true, margin: "-50px" }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
              How it works
            </motion.span>
            <Heading />
          </div>
          <motion.div className="art:max-w-xl art:@min-[1024px]/artemis:justify-self-end" initial={COPY_HIDDEN} animate={headerInView ? COPY_SHOWN : COPY_HIDDEN} transition={{ duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.28 }}>
            <p className="art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
              Capture what matters, shape it into an aligned plan, and move it live without losing the thinking that
              got you there.
            </p>
            <ArtemisButtonLink href="#" variant="secondary" size="md" className="art:mt-6 art:w-fit art:h-9">
              See the workflow
              <ArrowRight className="art:size-4"/>
            </ArtemisButtonLink>
          </motion.div>
        </div>
        <div className="art:relative art:mt-14 art:border art:border-border/70 art:@min-[640px]/artemis:mt-16">
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-top-2 art:-left-2")}/>
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-top-2 art:-right-2")}/>
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-bottom-2 art:-left-2")}/>
          <span aria-hidden="true" className={artemisCx(CORNER, "art:-right-2 art:-bottom-2")}/>
          <div className="art:grid art:@min-[768px]/artemis:grid-cols-3">
            {STEPS.map((step, index) => (<StepCard key={step.number} step={step} index={index} active={active === index} onSelect={() => setActive(index)}/>))}
          </div>
        </div>
      </div>
    </section>);
}

"use client";
// @zeus-internal
import { Check, ClipboardPenLine, Layers, MessageSquareText, MicVocal, Sparkles } from "lucide-react";
import { motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
const SHOWN = "translate3d(0,0,0)";
function captureRow(index: number, active: boolean) {
    return {
        animate: active
            ? { opacity: 1, transform: SHOWN }
            : { opacity: 0.55, transform: `translate3d(${index === 0 ? -14 : 14}px,0,0)` },
        transition: { duration: 0.45, ease: ARTEMIS_EASE_OUT, delay: active ? index * 0.08 : 0 },
    } as const;
}
export function CaptureScene({ active }: {
    active: boolean;
}) {
    return (<div className="art:mx-auto art:flex art:max-w-xs art:flex-col art:gap-2">
      <motion.div className="art:flex art:items-center art:gap-3 art:border art:border-border/70 art:bg-background/70 art:px-3.5 art:py-3 art:backdrop-blur-md" {...captureRow(0, active)}>
        <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground">
          <MessageSquareText strokeWidth={1.7} className="art:size-3.5"/>
        </span>
        <span className="art:font-medium art:text-xs">Customer note</span>
        <span className="art:ml-auto art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.12em]">Added</span>
      </motion.div>
      <motion.div className="art:flex art:items-center art:gap-3 art:border art:border-border/70 art:bg-background/70 art:px-3.5 art:py-3 art:backdrop-blur-md" {...captureRow(1, active)}>
        <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground">
