          <div className="art:flex art:h-24 art:items-end art:gap-2" aria-hidden="true">
            {TILE_SIZES.map((size, t) => (<span key={size} className={`${TILE_CLASS} ${size} ${current ? "art:translate-y-0 art:opacity-100" : "art:translate-y-1 art:opacity-70"}`} style={{ transitionDelay: `${current ? t * 45 : 0}ms`, transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }}>
                {t < TILE_SIZES.length - 1 ? (<span className="art:h-px art:w-5 art:bg-border"/>) : (<TileIcon className="art:size-5 art:text-foreground" aria-hidden="true"/>)}
              </span>))}
          </div>
          <p className="art:mt-5 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">{step.label}</p>
          <h3 className="art:mt-2 art:max-w-[20rem] art:text-pretty art:font-medium art:text-xl art:leading-tight art:tracking-[-0.025em]">{step.title}</h3>
          <p className="art:mt-3 art:max-w-[20rem] art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:line-clamp-2">
            {step.description}
          </p>
        </div>
      </div>
    </ArtemisButton>);
}

"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";
import { artemisWordMotion, type ArtemisWordMotionOptions } from "./word-motion";
export interface ArtemisWordEntranceProps {
  words: string[];
  className?: string;
  stagger?: number;
  delay?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: ArtemisWordMotionOptions["spring"];
  once?: boolean;
  amount?: number;
  entered?: boolean;
}
export function ArtemisWordEntrance({
  words,
  className = "",
  stagger = 0.055,
  delay = 0,
  blur = 10,
  yOffset = "20%",
  amount = 0.4,
  spring,
  once = true,
  entered: externalEntry,
}: ArtemisWordEntranceProps) {
  const element = useRef<HTMLSpanElement>(null);
  const observed = useInView(element, { once, amount });
  const entered = externalEntry ?? observed;
  const reduced = useReducedMotion() === true;
  return (
    <span ref={element} className={`art:block ${className}`}>
      <span className="art:block">
        {words.map((word, index) => {
          const movement = artemisWordMotion(index, reduced, {
            delay,
            stagger,
            blur,
            yOffset,
            spring,
          });
          return (
            <motion.span
              key={index}
              className="art:inline-block"
              initial={movement.initial}
              animate={entered ? movement.animate : undefined}
              transition={movement.transition}
            >
              {word}
              {index < words.length - 1 && (
                <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                  {"\u00a0"}
                </span>
              )}
            </motion.span>
          );
        })}
      </span>
    </span>
  );
}

// @zeus-internal
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisWordMotionOptions {
  delay?: number;
  stagger?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: { stiffness?: number; damping?: number; mass?: number };
}
export function artemisWordMotion(
  index: number,
  reduced: boolean,
  { delay = 0, stagger = 0.055, blur = 10, yOffset = "20%", spring }: ArtemisWordMotionOptions = {}
) {
  const offset = delay + index * stagger;
  return {
    initial: reduced ? { opacity: 0 } : { opacity: 0, filter: `blur(${blur}px)`, y: yOffset },
    animate: reduced ? { opacity: 1 } : { opacity: 1, filter: "blur(0px)", y: 0 },
    transition: reduced
      ? { opacity: { duration: 0.25, delay: offset * 0.3, ease: ARTEMIS_EASE_OUT } }
      : {
          opacity: { duration: 0.7, delay: offset, ease: ARTEMIS_EASE_OUT },
          filter: { duration: 0.9, delay: offset, ease: ARTEMIS_EASE_OUT },
          y: {
            type: "spring" as const,
            stiffness: spring?.stiffness ?? 140,
            damping: spring?.damping ?? 26,
            mass: spring?.mass ?? 1.2,
            delay: offset,
          },
        },
  };
}
